ALTER TABLE "attachment" DROP CONSTRAINT "attachment_bytes_bound", ADD CONSTRAINT "attachment_bytes_bound" CHECK (("conversation_id" is null or octet_length("bytes") <= 4000000) and (not ("task_id" is not null and num_nonnulls("inbox_item_id", "conversation_id", "description_comment_id") = 0) or octet_length("bytes") <= 1500000 or ("content_type" = 'video/webm' and octet_length("bytes") <= 4000000) or ("content_type" = 'application/pdf' and octet_length("bytes") <= 3000000)));